<?php include 'db.php'; require_role('Admin'); $page_title='Admin Dashboard'; include 'header.php'; function countTable($conn,$t){return $conn->query("SELECT COUNT(*) c FROM $t")->fetch_assoc()['c'];} $pay=$conn->query("SELECT IFNULL(SUM(Amount),0) s FROM PAYMENT")->fetch_assoc()['s']; ?>
<h2>Admin Dashboard</h2><div class="cards"><div class="card"><h3>Patients</h3><p><?=countTable($conn,'PATIENT')?></p></div><div class="card"><h3>Doctors</h3><p><?=countTable($conn,'DOCTOR')?></p></div><div class="card"><h3>Appointments</h3><p><?=countTable($conn,'APPOINTMENT')?></p></div><div class="card"><h3>Total Payments</h3><p><?=esc($pay)?></p></div></div>
<h3>Manage</h3><p><a class="btn" href="manage.php?table=PATIENT">Patients</a> <a class="btn" href="manage.php?table=DOCTOR">Doctors</a> <a class="btn" href="manage.php?table=NURSE">Nurses</a> <a class="btn" href="manage.php?table=ROOM">Rooms</a> <a class="btn" href="manage.php?table=RADIOLOGY_TEST">Tests</a> <a class="btn" href="manage.php?table=APPOINTMENT">Appointments</a> <a class="btn" href="manage.php?table=PAYMENT">Payments</a> <a class="btn" href="manage.php?table=FILE_UPLOAD">Files</a></p>
<h3>All Appointments</h3><table><tr><th>ID</th><th>Patient</th><th>Doctor</th><th>Nurse</th><th>Test</th><th>Room</th><th>Date</th><th>Status</th><th>Payment</th></tr><?php $q=$conn->query("SELECT A.*, CONCAT(P.First_Name,' ',P.Last_Name) Patient_Name, CONCAT(D.First_Name,' ',D.Last_Name) Doctor_Name, CONCAT(N.First_Name,' ',N.Last_Name) Nurse_Name, RT.Test_Name, R.Room_Name, Pay.Payment_Status FROM APPOINTMENT A JOIN PATIENT P ON A.Patient_ID=P.Patient_ID JOIN DOCTOR D ON A.Doctor_ID=D.Doctor_ID LEFT JOIN NURSE N ON A.Nurse_ID=N.Nurse_ID JOIN RADIOLOGY_TEST RT ON A.Test_ID=RT.Test_ID JOIN ROOM R ON A.Room_ID=R.Room_ID LEFT JOIN PAYMENT Pay ON A.Appointment_ID=Pay.Appointment_ID ORDER BY A.Appointment_ID DESC"); while($r=$q->fetch_assoc()): ?><tr><td><?=esc($r['Appointment_ID'])?></td><td><?=esc($r['Patient_Name'])?></td><td><?=esc($r['Doctor_Name'])?></td><td><?=esc($r['Nurse_Name'])?></td><td><?=esc($r['Test_Name'])?></td><td><?=esc($r['Room_Name'])?></td><td><?=esc($r['Appointment_Date'])?></td><td><?=esc($r['Status'])?></td><td><?=esc($r['Payment_Status']??'Not Paid')?></td></tr><?php endwhile; ?></table><?php include 'footer.php'; ?>